<script setup lang="ts">import { onMounted, ref } from 'vue'; import { RouterLink } from 'vue-router'; import { ArrowRight, PackageCheck, RotateCcw, ShieldCheck } from 'lucide-vue-next'; import { api } from '../api'; import type { Product } from '../stores'; import ProductCard from '../components/ProductCard.vue'; import { useCart,useSession } from '../stores'; const products=ref<Product[]>([]), error=ref('');const session=useSession(),cart=useCart();onMounted(async()=>{try{products.value=(await api<{items:Product[]}>('/products?limit=4')).items}catch{error.value='Catalog is unavailable right now.'}});async function add(id:string){if(!session.user)return location.assign('/login');try{await cart.add(id)}catch(e:any){error.value=e.message}}</script>
<template><main><section class="hero"><img src="https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&w=1800&q=85" alt="Modern clothing boutique"/><div><small>THE 2026 EDIT</small><h1>Refined simplicity for everyday living.</h1><p>Discover meticulously crafted essentials designed to elevate your lifestyle and home.</p><RouterLink class="button light" to="/products">Explore collection <ArrowRight :size="16"/></RouterLink></div></section><section class="container section"><div class="section-head"><div><small>EXPLORE</small><h2>Curated categories</h2></div><RouterLink to="/products">Shop everything →</RouterLink></div><div class="categories"><RouterLink to="/products?category=fashion"><img src="https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&w=700&q=80"/><span>Apparel</span></RouterLink><RouterLink to="/products?category=electronics"><img src="https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=700&q=80"/><span>Audio & Tech</span></RouterLink><RouterLink to="/products?category=home-living"><img src="https://images.unsplash.com/photo-1513694203232-719a280e022f?auto=format&fit=crop&w=700&q=80"/><span>Home living</span></RouterLink></div></section><section class="muted section"><div class="container"><div class="section-head"><div><small>CURATED HIGHLIGHTS</small><h2>Featured arrivals</h2></div><RouterLink to="/products">View all products →</RouterLink></div><p v-if="error" class="notice">{{error}}</p><div class="products"><ProductCard v-for="p in products" :key="p.id" :product="p" @add="add"/></div></div></section><section class="container benefits"><div><PackageCheck/><b>Express shipping</b><p>Dispatched within 24 hours.</p></div><div><RotateCcw/><b>Easy returns</b><p>14-day hassle-free returns.</p></div><div><ShieldCheck/><b>Secure checkout</b><p>Your information stays protected.</p></div></section></main></template>
